from __future__ import annotations
import math

def kl_exp(a: float, b: float) -> float:
    if a <= 0 or b <= 0: raise ValueError("positive rates required")
    u = (b-a)/a
    return u-math.log1p(u)

def compare(n: int) -> tuple[float, float, float]:
    direct=math.fsum(kl_exp(k+1.0,k+2.0) for k in range(n))
    telescoped=math.fsum(1.0/j for j in range(1,n+1))-math.log(n+1.0)
    return direct,telescoped,abs(direct-telescoped)

if __name__ == "__main__":
    for n in (1,10,100,1000): print(n, compare(n))

from __future__ import annotations
import math
GAMMA=0.5772156649015328606

def enclosure(n: int) -> tuple[float,float]:
    if n < 1: raise ValueError("n must be positive")
    s=math.fsum(1.0/j for j in range(1,n+1))-math.log(n+1.0)
    return s+1/(2*(n+1)),s+1/(2*n)

if __name__ == "__main__":
    for n in (10,100,1000,10000):
        lo,hi=enclosure(n); print(n,lo,GAMMA,hi,lo<=GAMMA<=hi)

from __future__ import annotations
import math

def fisher_comparison(k: int) -> tuple[float,float,float]:
    if k < 0: raise ValueError("k must be nonnegative")
    m=float(k+1); exact=1/m-math.log1p(1/m)
    quadratic=1/(2*m*m)
    return exact,quadratic,exact/quadratic

if __name__ == "__main__":
    for k in (0,1,4,9,99,999): print(k,fisher_comparison(k))

